\set ON_ERROR_STOP on
BEGIN;
DO $$ DECLARE failures integer; BEGIN

  IF current_user<>'certification-administrator' THEN RAISE EXCEPTION 'verification requires the reviewed brokered administrator'; END IF;
  IF current_database() !~ '^mscqr_full_rls_cert_[a-z0-9_]+$' THEN RAISE EXCEPTION 'verification is bound to the reviewed green database'; END IF;
  IF NOT EXISTS (SELECT 1 FROM mscqr_rls_install.state WHERE singleton
    AND target_environment='certification'
    AND deployment_id='cert'
    AND green_database=current_database()
    AND source_contract_sha256='745d713cf284dde78b13e04a815d333cbf9eeed589e6662f98a0d97642dcd5b0'
    AND package_role_marker='mscqr-full-rls-clean-room:certification:745d713cf284dde78b13e04a815d333cbf9eeed589e6662f98a0d97642dcd5b0'
    AND administrator_role='certification-administrator'
    AND phase='policies-installed'
    AND NOT traffic_enabled) THEN RAISE EXCEPTION 'verification lacks the exact clean-room package marker'; END IF;

  IF (SELECT count(*) FROM pg_roles WHERE rolname IN ('mscqr_rls_cert_owner', 'mscqr_rls_cert_auth_owner', 'mscqr_rls_cert_app', 'mscqr_rls_cert_read', 'mscqr_rls_cert_preauth', 'mscqr_rls_cert_worker', 'mscqr_rls_cert_scheduled', 'mscqr_rls_cert_operator', 'mscqr_rls_cert_migration'))<>9
     OR EXISTS (SELECT 1 FROM pg_roles r JOIN (VALUES ('mscqr_rls_cert_owner', false),
    ('mscqr_rls_cert_auth_owner', false),
    ('mscqr_rls_cert_app', true),
    ('mscqr_rls_cert_read', true),
    ('mscqr_rls_cert_preauth', true),
    ('mscqr_rls_cert_worker', true),
    ('mscqr_rls_cert_scheduled', true),
    ('mscqr_rls_cert_operator', true),
    ('mscqr_rls_cert_migration', true)) spec(role_name,expected_login) ON spec.role_name=r.rolname WHERE r.rolcanlogin IS DISTINCT FROM spec.expected_login OR r.rolinherit OR r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls OR obj_description(r.oid,'pg_authid')<>'mscqr-full-rls-clean-room:certification:745d713cf284dde78b13e04a815d333cbf9eeed589e6662f98a0d97642dcd5b0')
  THEN RAISE EXCEPTION 'managed role attributes or package markers drifted'; END IF;

  IF (SELECT count(*) FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid WHERE parent.rolname IN ('mscqr_rls_cert_owner', 'mscqr_rls_cert_auth_owner', 'mscqr_rls_cert_app', 'mscqr_rls_cert_read', 'mscqr_rls_cert_preauth', 'mscqr_rls_cert_worker', 'mscqr_rls_cert_scheduled', 'mscqr_rls_cert_operator', 'mscqr_rls_cert_migration'))<>18
     OR EXISTS (SELECT 1 FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid JOIN pg_roles member ON member.oid=m.member WHERE parent.rolname IN ('mscqr_rls_cert_owner', 'mscqr_rls_cert_auth_owner', 'mscqr_rls_cert_app', 'mscqr_rls_cert_read', 'mscqr_rls_cert_preauth', 'mscqr_rls_cert_worker', 'mscqr_rls_cert_scheduled', 'mscqr_rls_cert_operator', 'mscqr_rls_cert_migration') AND (member.rolname<>'certification-administrator' OR m.inherit_option OR (m.admin_option=m.set_option)))
     OR EXISTS (SELECT 1 FROM pg_roles parent WHERE parent.rolname IN ('mscqr_rls_cert_owner', 'mscqr_rls_cert_auth_owner', 'mscqr_rls_cert_app', 'mscqr_rls_cert_read', 'mscqr_rls_cert_preauth', 'mscqr_rls_cert_worker', 'mscqr_rls_cert_scheduled', 'mscqr_rls_cert_operator', 'mscqr_rls_cert_migration') AND ((SELECT count(*) FROM pg_auth_members m JOIN pg_roles member ON member.oid=m.member WHERE m.roleid=parent.oid AND member.rolname='certification-administrator' AND m.admin_option AND NOT m.inherit_option AND NOT m.set_option)<>1 OR (SELECT count(*) FROM pg_auth_members m JOIN pg_roles member ON member.oid=m.member JOIN pg_roles grantor ON grantor.oid=m.grantor WHERE m.roleid=parent.oid AND member.rolname='certification-administrator' AND grantor.rolname='certification-administrator' AND NOT m.admin_option AND NOT m.inherit_option AND m.set_option)<>1))
     OR EXISTS (SELECT 1 FROM pg_auth_members m JOIN pg_roles member ON member.oid=m.member WHERE member.rolname IN ('mscqr_rls_cert_owner', 'mscqr_rls_cert_auth_owner', 'mscqr_rls_cert_app', 'mscqr_rls_cert_read', 'mscqr_rls_cert_preauth', 'mscqr_rls_cert_worker', 'mscqr_rls_cert_scheduled', 'mscqr_rls_cert_operator', 'mscqr_rls_cert_migration'))
  THEN RAISE EXCEPTION 'managed role membership topology drifted'; END IF;

  IF EXISTS (
    (SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') EXCEPT SELECT table_name FROM (VALUES ('ActionIdempotencyKey'),('AdminMfaCredential'),('AdminWebAuthnCredential'),('AllocationEvent'),('AuditLog'),('AuditLogOutbox'),('AuthMfaChallenge'),('AuthSessionRiskSignal'),('AuthWebAuthnChallenge'),('Batch'),('BatchPrintPackToken'),('CompliancePackJob'),('CustomerTrustCredential'),('CustomerTrustIntake'),('CustomerVerificationSession'),('CustomerWebAuthnChallenge'),('CustomerWebAuthnCredential'),('DegradationEvent'),('EmailVerificationToken'),('EvidenceRetentionJob'),('EvidenceRetentionPolicy'),('ForensicEventChain'),('Incident'),('IncidentCommunication'),('IncidentEvent'),('IncidentEvidence'),('IncidentEvidenceFingerprint'),('IncidentHandoff'),('InventoryStatusRollup'),('Invite'),('Licensee'),('ManufacturerLicenseeLink'),('MfaLoginChallenge'),('Notification'),('Organization'),('Ownership'),('OwnershipTransfer'),('PasswordReset'),('PolicyAlert'),('PolicyRule'),('PrintAuditEvent'),('PrintItem'),('PrintItemEvent'),('PrintJob'),('PrintJobChunk'),('PrintReissueRequest'),('PrintRenderToken'),('PrintSession'),('Printer'),('PrinterAgentSession'),('PrinterAttestation'),('PrinterProfile'),('PrinterProfileSnapshot'),('PrinterRegistration'),('QRCode'),('QRRange'),('QrAllocationRequest'),('QrScanLog'),('RefreshToken'),('ReplacementChain'),('RequestAccess'),('RouteTransitionMetric'),('ScanMetricsHourlyRollup'),('ScheduledJobCredential'),('SecurityEventOutbox'),('SecurityPolicy'),('SensitiveActionApproval'),('SupportIssueReport'),('SupportTicket'),('SupportTicketMessage'),('SystemCheckpoint'),('TenantFeatureFlag'),('TraceEvent'),('User'),('UserBackupCode'),('UserMfaFactor'),('VerificationDecision'),('VerificationEvidenceSnapshot'),('_prisma_migrations')) expected(table_name))
    UNION ALL
    (SELECT table_name FROM (VALUES ('ActionIdempotencyKey'),('AdminMfaCredential'),('AdminWebAuthnCredential'),('AllocationEvent'),('AuditLog'),('AuditLogOutbox'),('AuthMfaChallenge'),('AuthSessionRiskSignal'),('AuthWebAuthnChallenge'),('Batch'),('BatchPrintPackToken'),('CompliancePackJob'),('CustomerTrustCredential'),('CustomerTrustIntake'),('CustomerVerificationSession'),('CustomerWebAuthnChallenge'),('CustomerWebAuthnCredential'),('DegradationEvent'),('EmailVerificationToken'),('EvidenceRetentionJob'),('EvidenceRetentionPolicy'),('ForensicEventChain'),('Incident'),('IncidentCommunication'),('IncidentEvent'),('IncidentEvidence'),('IncidentEvidenceFingerprint'),('IncidentHandoff'),('InventoryStatusRollup'),('Invite'),('Licensee'),('ManufacturerLicenseeLink'),('MfaLoginChallenge'),('Notification'),('Organization'),('Ownership'),('OwnershipTransfer'),('PasswordReset'),('PolicyAlert'),('PolicyRule'),('PrintAuditEvent'),('PrintItem'),('PrintItemEvent'),('PrintJob'),('PrintJobChunk'),('PrintReissueRequest'),('PrintRenderToken'),('PrintSession'),('Printer'),('PrinterAgentSession'),('PrinterAttestation'),('PrinterProfile'),('PrinterProfileSnapshot'),('PrinterRegistration'),('QRCode'),('QRRange'),('QrAllocationRequest'),('QrScanLog'),('RefreshToken'),('ReplacementChain'),('RequestAccess'),('RouteTransitionMetric'),('ScanMetricsHourlyRollup'),('ScheduledJobCredential'),('SecurityEventOutbox'),('SecurityPolicy'),('SensitiveActionApproval'),('SupportIssueReport'),('SupportTicket'),('SupportTicketMessage'),('SystemCheckpoint'),('TenantFeatureFlag'),('TraceEvent'),('User'),('UserBackupCode'),('UserMfaFactor'),('VerificationDecision'),('VerificationEvidenceSnapshot'),('_prisma_migrations')) expected(table_name) EXCEPT SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p'))
  ) THEN RAISE EXCEPTION 'post-migration table inventory differs from the reviewed zero-based Prisma schema'; END IF;
  IF EXISTS (
    (SELECT t.typname FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype='e' EXCEPT SELECT type_name FROM (VALUES ('AlertSeverity'),('AuditLogOutboxStatus'),('AuthRiskLevel'),('BatchLifecycleState'),('CompliancePackJobStatus'),('CustomerTrustLevel'),('CustomerTrustReviewState'),('CustomerVerificationAuthState'),('CustomerVerificationEntryMethod'),('EvidenceRetentionJobStatus'),('ForensicEventType'),('IncidentActorType'),('IncidentCommChannel'),('IncidentCommDirection'),('IncidentCommStatus'),('IncidentContactMethod'),('IncidentEventType'),('IncidentHandoffStage'),('IncidentPriority'),('IncidentReportedBy'),('IncidentResolutionOutcome'),('IncidentSeverity'),('IncidentStatus'),('IncidentType'),('NotificationAudience'),('NotificationChannel'),('OwnershipTransferStatus'),('PolicyAlertType'),('PolicyRuleType'),('PrintDispatchMode'),('PrintItemEventType'),('PrintItemState'),('PrintJobStatus'),('PrintPayloadType'),('PrintPipelineState'),('PrintSessionStatus'),('PrinterCommandLanguage'),('PrinterConnectionType'),('PrinterDeliveryMode'),('PrinterLanguageKind'),('PrinterProfileSnapshotType'),('PrinterProfileStatus'),('PrinterTransportKind'),('PrinterTrustStatus'),('QRStatus'),('QrAllocationRequestStatus'),('ReissueRequestStatus'),('ReplacementChainStatus'),('SecurityEventDeliveryStatus'),('SupportTicketStatus'),('TraceEventType'),('UserRole'),('UserStatus'),('VerificationDecisionOutcome'),('VerificationDegradationMode'),('VerificationProofTier'),('VerificationReplacementStatus'),('VerificationRiskBand')) expected(type_name))
    UNION ALL
    (SELECT type_name FROM (VALUES ('AlertSeverity'),('AuditLogOutboxStatus'),('AuthRiskLevel'),('BatchLifecycleState'),('CompliancePackJobStatus'),('CustomerTrustLevel'),('CustomerTrustReviewState'),('CustomerVerificationAuthState'),('CustomerVerificationEntryMethod'),('EvidenceRetentionJobStatus'),('ForensicEventType'),('IncidentActorType'),('IncidentCommChannel'),('IncidentCommDirection'),('IncidentCommStatus'),('IncidentContactMethod'),('IncidentEventType'),('IncidentHandoffStage'),('IncidentPriority'),('IncidentReportedBy'),('IncidentResolutionOutcome'),('IncidentSeverity'),('IncidentStatus'),('IncidentType'),('NotificationAudience'),('NotificationChannel'),('OwnershipTransferStatus'),('PolicyAlertType'),('PolicyRuleType'),('PrintDispatchMode'),('PrintItemEventType'),('PrintItemState'),('PrintJobStatus'),('PrintPayloadType'),('PrintPipelineState'),('PrintSessionStatus'),('PrinterCommandLanguage'),('PrinterConnectionType'),('PrinterDeliveryMode'),('PrinterLanguageKind'),('PrinterProfileSnapshotType'),('PrinterProfileStatus'),('PrinterTransportKind'),('PrinterTrustStatus'),('QRStatus'),('QrAllocationRequestStatus'),('ReissueRequestStatus'),('ReplacementChainStatus'),('SecurityEventDeliveryStatus'),('SupportTicketStatus'),('TraceEventType'),('UserRole'),('UserStatus'),('VerificationDecisionOutcome'),('VerificationDegradationMode'),('VerificationProofTier'),('VerificationReplacementStatus'),('VerificationRiskBand')) expected(type_name) EXCEPT SELECT t.typname FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype='e')
  ) THEN RAISE EXCEPTION 'post-migration enum inventory differs from the reviewed Prisma schema'; END IF;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('S','v','m','f'))
     OR EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public')
  THEN RAISE EXCEPTION 'post-migration inventory contains an unreviewed public object class'; END IF;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname='public' AND c.relname IN ('ActionIdempotencyKey', 'AdminMfaCredential', 'AdminWebAuthnCredential', 'AllocationEvent', 'AuditLog', 'AuditLogOutbox', 'AuthMfaChallenge', 'AuthSessionRiskSignal', 'AuthWebAuthnChallenge', 'Batch', 'BatchPrintPackToken', 'CompliancePackJob', 'CustomerTrustCredential', 'CustomerTrustIntake', 'CustomerVerificationSession', 'CustomerWebAuthnChallenge', 'CustomerWebAuthnCredential', 'DegradationEvent', 'EmailVerificationToken', 'EvidenceRetentionJob', 'EvidenceRetentionPolicy', 'ForensicEventChain', 'Incident', 'IncidentCommunication', 'IncidentEvent', 'IncidentEvidence', 'IncidentEvidenceFingerprint', 'IncidentHandoff', 'InventoryStatusRollup', 'Invite', 'Licensee', 'ManufacturerLicenseeLink', 'MfaLoginChallenge', 'Notification', 'Organization', 'Ownership', 'OwnershipTransfer', 'PasswordReset', 'PolicyAlert', 'PolicyRule', 'PrintAuditEvent', 'Printer', 'PrinterAgentSession', 'PrinterAttestation', 'PrinterProfile', 'PrinterProfileSnapshot', 'PrinterRegistration', 'PrintItem', 'PrintItemEvent', 'PrintJob', 'PrintJobChunk', 'PrintReissueRequest', 'PrintRenderToken', 'PrintSession', 'QrAllocationRequest', 'QRCode', 'QRRange', 'QrScanLog', 'RefreshToken', 'ReplacementChain', 'RequestAccess', 'RouteTransitionMetric', 'ScanMetricsHourlyRollup', 'ScheduledJobCredential', 'SecurityEventOutbox', 'SecurityPolicy', 'SensitiveActionApproval', 'SupportIssueReport', 'SupportTicket', 'SupportTicketMessage', 'SystemCheckpoint', 'TenantFeatureFlag', 'TraceEvent', 'User', 'UserBackupCode', 'UserMfaFactor', 'VerificationDecision', 'VerificationEvidenceSnapshot') AND r.rolname<>'mscqr_rls_cert_owner') THEN RAISE EXCEPTION 'application table ownership drifted'; END IF;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname='public' AND c.relname='_prisma_migrations' AND r.rolname<>'mscqr_rls_cert_migration') THEN RAISE EXCEPTION 'Prisma migration ledger ownership drifted'; END IF;
  IF EXISTS (SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_roles r ON r.oid=t.typowner WHERE n.nspname='public' AND t.typtype='e' AND r.rolname<>'mscqr_rls_cert_owner') THEN RAISE EXCEPTION 'Prisma enum ownership drifted'; END IF;
  IF EXISTS (SELECT 1 FROM pg_namespace n JOIN pg_roles r ON r.oid=n.nspowner WHERE (n.nspname IN ('public','app_rls') AND r.rolname<>'mscqr_rls_cert_owner') OR (n.nspname='app_auth' AND r.rolname<>'mscqr_rls_cert_auth_owner') OR (n.nspname='mscqr_rls_install' AND r.rolname<>'certification-administrator')) THEN RAISE EXCEPTION 'clean-room schema ownership drifted'; END IF;
  IF EXISTS (
    (SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='mscqr_rls_install' AND c.relkind='r' EXCEPT SELECT * FROM (VALUES ('expected_policy'),('expected_routine'),('state')) expected(table_name))
    UNION ALL
    (SELECT * FROM (VALUES ('expected_policy'),('expected_routine'),('state')) expected(table_name) EXCEPT SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='mscqr_rls_install' AND c.relkind='r')
  ) OR EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname='mscqr_rls_install' AND c.relkind='r' AND r.rolname<>'certification-administrator')
    OR EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) acl WHERE n.nspname='mscqr_rls_install' AND c.relkind='r' AND acl.grantee<>c.relowner)
  THEN RAISE EXCEPTION 'private install-state inventory or privileges drifted'; END IF;
  SELECT count(*) INTO failures FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('ActionIdempotencyKey','AdminMfaCredential','AdminWebAuthnCredential','AllocationEvent','AuditLog','AuditLogOutbox','AuthMfaChallenge','AuthSessionRiskSignal','AuthWebAuthnChallenge','Batch','CompliancePackJob','CustomerTrustCredential','CustomerTrustIntake','CustomerVerificationSession','CustomerWebAuthnChallenge','CustomerWebAuthnCredential','DegradationEvent','EmailVerificationToken','EvidenceRetentionJob','EvidenceRetentionPolicy','ForensicEventChain','Incident','IncidentCommunication','IncidentEvent','IncidentEvidence','IncidentEvidenceFingerprint','IncidentHandoff','InventoryStatusRollup','Invite','Licensee','ManufacturerLicenseeLink','MfaLoginChallenge','Notification','Organization','Ownership','OwnershipTransfer','PasswordReset','PolicyAlert','PolicyRule','PrintAuditEvent','Printer','PrinterAgentSession','PrinterAttestation','PrinterProfile','PrinterProfileSnapshot','PrinterRegistration','PrintItem','PrintItemEvent','PrintJob','PrintJobChunk','PrintReissueRequest','PrintSession','QrAllocationRequest','QRCode','QRRange','QrScanLog','RefreshToken','ReplacementChain','RequestAccess','RouteTransitionMetric','ScanMetricsHourlyRollup','ScheduledJobCredential','SecurityEventOutbox','SecurityPolicy','SensitiveActionApproval','SupportIssueReport','SupportTicket','SupportTicketMessage','SystemCheckpoint','TenantFeatureFlag','TraceEvent','User','UserBackupCode','UserMfaFactor','VerificationDecision','VerificationEvidenceSnapshot') AND c.relkind IN ('r','p') AND (NOT c.relrowsecurity OR NOT c.relforcerowsecurity); IF failures<>0 THEN RAISE EXCEPTION 'FORCE RLS verification failed for % tables',failures; END IF;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('BatchPrintPackToken','PrintRenderToken') AND (c.relrowsecurity OR c.relforcerowsecurity)) THEN RAISE EXCEPTION 'migration-only table unexpectedly has RLS state'; END IF;
  IF EXISTS (
    (SELECT tablename,policyname,cmd FROM pg_policies WHERE schemaname='public' EXCEPT SELECT * FROM (VALUES ('ActionIdempotencyKey','c01_administration_actionidempotencykey_insert','INSERT'),('ActionIdempotencyKey','c01_administration_actionidempotencykey_select','SELECT'),('ActionIdempotencyKey','c01_administration_actionidempotencykey_update','UPDATE'),('ActionIdempotencyKey','c03_capability_actionidempotencykey_insert','INSERT'),('ActionIdempotencyKey','c03_capability_actionidempotencykey_select','SELECT'),('ActionIdempotencyKey','c03_capability_actionidempotencykey_update','UPDATE'),('ActionIdempotencyKey','printing_lifecycle_actionidempotencykey_insert','INSERT'),('ActionIdempotencyKey','printing_lifecycle_actionidempotencykey_select','SELECT'),('ActionIdempotencyKey','printing_lifecycle_actionidempotencykey_update','UPDATE'),('ActionIdempotencyKey','scheduled_capability_actionidempotencykey_insert','INSERT'),('ActionIdempotencyKey','scheduled_capability_actionidempotencykey_select','SELECT'),('ActionIdempotencyKey','scheduled_capability_actionidempotencykey_update','UPDATE'),('AdminMfaCredential','b01_adminmfacredential_select','SELECT'),('AdminMfaCredential','b01_auth_closure_adminmfacredential_select','SELECT'),('AdminWebAuthnCredential','b01_adminwebauthncredential_select','SELECT'),('AdminWebAuthnCredential','b01_auth_closure_adminwebauthncredential_select','SELECT'),('AllocationEvent','qr_system_allocationevent_insert','INSERT'),('AuditLog','b03_outbox_auditlog_insert','INSERT'),('AuditLog','c01_administration_auditlog_insert','INSERT'),('AuditLog','c03_capability_auditlog_select','SELECT'),('AuditLog','full_rls_auditlog_insert_sql_profile_risk_analytics__0f42474373','INSERT'),('AuditLog','full_rls_auditlog_insert_sql_profile_risk_analytics__fa8df9e7e5','INSERT'),('AuditLog','full_rls_auditlog_select_sql_profile_audit_log_licen_9fc3407041','SELECT'),('AuditLog','full_rls_auditlog_select_sql_profile_audit_log_manuf_76949345a1','SELECT'),('AuditLog','full_